// TCP is a transport-layer protocol.
// In Node.js, the net module provides TCP sockets.
// The application does not manually implement
// sequence numbers, ACKs, retransmissions, etc.
// TCP handles those details underneath.

import net from 'node:net'

const server = net.createServer((socket) => {
  console.log('client connected:', socket.remoteAddress)

  socket.on('data', (chunk) => {
    socket.write(chunk) // echo the received data
  })

  socket.on('end', () => {
    console.log('client finished sending data')
  })
})

server.listen(4000, () => {
  console.log('TCP server listening on port 4000')
})

